update cellar.products set proof = 86.0, mash_style = 'traditional', mash_bill = '74% Corn, 14% Malted Rye, 12% Malted Barley', name = 'Cedar Ridge Original 86', expression = 'Original 86', aliases = (select array_agg(distinct a) from unnest(array_append(aliases, 'Cedar Ridge Bourbon')) a), producer = coalesce(producer, 'Cedar Ridge'), producer_id = coalesce(producer_id, '0af9c76d-a6dc-4f97-a476-e0f93d314c55'::uuid), source = 'maker', source_url = 'https://cedarridgedistillery.com/whiskeys/straight-bourbon-whiskey/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = 'b62f1a0a-1b16-4ae5-b6e8-c1baae49e2f5' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('b62f1a0a-1b16-4ae5-b6e8-c1baae49e2f5');
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
